// Importieren der notwendigen Module aus dem Hugging Face Hub
import { InferenceClient } from 'huggingface_hub';

// Erstellen eines neuen Clients mit dem bereitgestellten API-Key
const client = new InferenceClient({ apiKey: "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" });

// Definieren der Nachrichten, die an das Modell gesendet werden
const messages = [
    { role: "user", content: "Tell me a story" }
];

// Erstellen einer Chat-Completion-Anfrage mit den angegebenen Parametern
const stream = client.chat.completions.create({
    model: "Qwen/Qwen2.5-Coder-32B-Instruct", 
    messages: messages, 
    temperature: 0.5,
    max_tokens: 2048,
    top_p: 0.7,
    stream: true
});

// Streamen der Antwort des Modells und Ausgabe der Inhalte in der Konsole
for await (const chunk of stream) {
    console.log(chunk.choices[0].delta.content);
}
```

